-- PT111-S1-Q9. Batch 13.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT111-S1-Q9$batch13$ AND q.stimulus=$batch13$Researcher: The rate of psychological problems is higher among children of divorced parents than among other children. But it would be a mistake to conclude that these problems are caused by the difficulty the children have adjusting to divorce. It is just as reasonable to infer that certain behaviors that increase the likelihood of divorce—hostility, distrust, lack of empathy—are learned by children from their parents, and that it is these learned behaviors, rather than the difficulty of adjusting to divorce, that cause the children’s psychological problems.$batch13$ AND q.prompt=$batch13$The assertion that children of divorced parents have a higher rate of psychological problems than other children figures in the argument in which one of the following ways?$batch13$ AND q.correct_choice=$batch13$E$batch13$) THEN RAISE EXCEPTION 'Question changed: PT111-S1-Q9'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch13$PT111-S1-Q9$batch13$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT111-S1-Q9'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT111-S1-Q9$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Opposing Point$batch13$, $batch13$Children's psychological problems are caused by the difficulty they have adjusting to divorce.$batch13$), (1, $batch13$Conclusion$batch13$, $batch13$That inference is a mistake. It is just as reasonable to think the children learned hostility, distrust and lack of empathy from their parents, and that these learned behaviors cause the problems.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$The first sentence is a fact both sides accept: children of divorced parents have more psychological problems. The dispute is about why. One explanation blames adjusting to divorce. The researcher offers another that is just as reasonable. So the first sentence is the finding both explanations try to account for.$batch13$), (3, $batch13$Goal$batch13$, $batch13$Find the answer that treats the higher rate as an accepted finding the argument explains.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT111-S1-Q9$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$The conclusion is that blaming the divorce adjustment is a mistake. The rate is only the starting fact.$batch13$), ($batch13$B$batch13$, $batch13$This is the most popular trap. The argument does refute something, but it's the causal claim about adjusting to divorce. The researcher never doubts the rate itself.$batch13$), ($batch13$C$batch13$, $batch13$The argument never says divorce harms children. It suggests the learned behaviors do.$batch13$), ($batch13$D$batch13$, $batch13$The stimulus says these behaviors increase the likelihood of divorce, but the higher rate of problems isn't offered as evidence for that.$batch13$), ($batch13$E$batch13$, $batch13$The higher rate is treated as true, and the argument proposes the learned-behavior explanation for it.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT111-S1-Q9$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
